// counter.service.ts
import { Injectable } from '@angular/core';

@Injectable({ providedIn: 'root' })
export class CounterService {
  private count = 0;

  increment() { this.count++; }
  decrement() { this.count--; }
  getCount() { return this.count; }
}

// counter-display.component.ts
import { Component } from '@angular/core';
import { CounterService } from '../counter.service';

@Component({
  selector: 'app-counter-display',
  template: `<h2>Count: {{ counterService.getCount() }}</h2>`
})
export class CounterDisplayComponent {
  constructor(public counterService: CounterService) {}
}

// counter-controls.component.ts
import { Component } from '@angular/core';
import { CounterService } from '../counter.service';

@Component({
  selector: 'app-counter-controls',
  template: `
    <button (click)="counterService.increment()">+</button>
    <button (click)="counterService.decrement()">-</button>
  `
})
export class CounterControlsComponent {
  constructor(public counterService: CounterService) {}
}

// app.component.html
<app-counter-controls></app-counter-controls>
<app-counter-display></app-counter-display>
